<?php
namespace App\Http\Controllers;
use App\Models\Cheque;use App\Services\ChequeAccessService;use Illuminate\Http\Request;
class ChequeListController extends Controller { public function __invoke(Request$r,string$view,ChequeAccessService$a){$q=$a->scope(Cheque::with(['customer','supplier']),$r->user());$title=match($view){'upcoming'=>'Upcoming Cheques','today'=>'Today Cheques','overdue'=>'Overdue / Pending Cheques','passed'=>'Passed Cheques','returned'=>'Returned Cheques',default=>'Cheques'};match($view){'upcoming'=>$q->open()->whereBetween('cheque_date',[today(),today()->addDays((int)\App\Models\Setting::get('cheque_reminder_days',3))]),'today'=>$q->open()->whereDate('cheque_date',today()),'overdue'=>$q->open()->whereDate('cheque_date','<',today()),'passed'=>$q->where('status','passed'),'returned'=>$q->where('status','returned'),default=>$q};app(ChequeReportController::class)->filters($q,$r);$cheques=$q->orderBy('cheque_date')->paginate(25)->withQueryString();$type='all';return view('cheques.index',compact('cheques','type','title'));} }
